254.         var awaiter = new CountDownLatch(1);
255.         context.runOnContext(
256.                 v -> {
257.                     try {
258.                         if (data == null) // end of stream
259.                         endHandler.handle(null);
260.                         else dataHandler.handle(data);
261.                         awaiter.countDown();
262.                     } catch (Throwable t) {
263.                         errorHandler.handle(t);
264.                         awaiter.countDown();
265.                     }
266.                 });
